async function main(ctx) {
  // Extract child conversation id from create_child_conversation response
  let childConversationId = '';
  try {
    const raw = ctx.lastOutputOf('create_child_conversation') || {};
    const payload = (raw && typeof raw === 'object' && Object.prototype.hasOwnProperty.call(raw, 'body'))
      ? raw.body
      : raw;
    const data = payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'data')
      ? payload.data
      : payload;
    if (data && typeof data === 'object' && data.id) {
      childConversationId = String(data.id);
    }
  } catch (e) {}

  // TOOL_CALL_MESSAGE_ID is only present when this tool is executed from an assistant tool call message.
  let messageId = '';
  try {
    const v = ctx.env && ctx.env('TOOL_CALL_MESSAGE_ID');
    if (v) messageId = String(v);
  } catch (e) {}

  const shouldLink = Boolean(messageId && childConversationId);

  return {
    shouldLink,
    messageId: messageId || null,
    linkedConversationId: childConversationId || null,
    childConversationId: childConversationId || null,
  };
}
